    hp: 25,
    speed: 4.8,
    radius: 0.6,
    reach: 14.0,
    windup: 0.5,
    damage: 8,
    flies: true,
    ranged: true,
    targets: 'player',
    pack: 2,
    drop: Object.freeze({ item: 'pixels', n: 4 }),
  }),
  brute: Object.freeze({
    hp: 100,
    speed: 2.4,
    radius: 1.2,
    reach: 2.2,
    windup: 1.0,
    damage: 30,
    flies: false,
    ranged: false,
    targets: 'player',
